let url = "https://control.msg91.com/api/v5/flow/";

let authkey = "YOUR_MSG91_AUTHKEY_HERE";  // placeholder, main baad mein replace karunga

let flow_id = "YOUR_FLOW_ID_HERE";  // yeh dashboard se milega

let sender = "DORAAH";  // your sender ID

let mobiles = identifier;  // phone number with +91

let variables = "OTP:" # otp;  // adjust as per your template variables

let body_text = "{\"flow_id\":\"" # flow_id # "\", \"sender\":\"" # sender # "\", \"mobiles\":\"" # mobiles # "\", \"VAR1\":\"" # otp # "\"}";  // simple payload for OTP

let request : Http.Request = {
  url = url;
  max_response_bytes = ?2000000;
  headers = [
    ("authkey", authkey),
    ("Content-Type", "application/json")
  ];
  body = ?Text.encodeUtf8(body_text);
  method = #post;
  transform = null;
};

Cycles.add<system>(1000000000000);  // 1T cycles, adjust if needed

let response = await Http.http_request(request);

switch(response.status) {
  case (200) { "OTP sent successfully" };
  case (_) { "SMS send failed: status " # Nat.toText(response.status) };
};
